/* Banque de questions supplémentaires : mathématiques, chapitres 1 à 9 (nombres, calculs, proportionnalité, calcul littéral, grandeurs et mesures) */
window.BANK = window.BANK || {};

BANK['maths/1'] = [
  { q: "Dans le nombre 6 482 019, quel est le chiffre des centaines de mille ?", choices: ["6", "4", "8", "2"], answer: 1, expl: "On découpe en classes : 6 | 482 | 019. Dans la classe des mille (482), le premier chiffre est celui des <b>centaines de mille</b> : c’est <b>4</b>. Piège : prendre le 6, qui est le chiffre des unités de millions." },
  { q: "Combien y a-t-il de centaines dans 6 482 019 ?", answers: ["64820", "64 820"], expl: "On cache tout ce qui est à droite de la colonne des centaines : 64 820|19. Il y a <b>64 820 centaines</b> (et 19 unités en plus). Le <i>chiffre</i> des centaines, lui, n’est que 0." },
  { q: "Quel nombre est égal à 3 × 10⁵ + 4 × 10³ + 2 × 10 ?", choices: ["304 020", "34 020", "304 200", "3 040 020"], answer: 0, expl: "3 × 100 000 + 4 × 1 000 + 2 × 10 = 300 000 + 4 000 + 20 = <b>304 020</b>. Pense à mettre des 0 aux rangs absents (dizaines de mille, centaines, unités)." },
  { q: "Quel nombre est formé de 12 milliers, 35 dizaines et 7 unités ?", answers: ["12357", "12 357"], expl: "C’est une décomposition non canonique : 12 milliers = 12 000, 35 dizaines = 350. Donc 12 000 + 350 + 7 = <b>12 357</b>. Attention : 35 dizaines ne tiennent pas dans une seule colonne, cela fait 3 centaines et 5 dizaines." },
  { q: "Vrai ou faux : 4 milliers, c’est la même chose que 400 dizaines.", type: 'vf', answer: 0, expl: "Vrai : 1 millier = 100 dizaines, donc 4 milliers = 400 dizaines (4 000 = 400 × 10). C’est exactement ce qu’on fait quand on « casse » un millier en barres de dix." },
  { q: "Un élève affirme que « 4 dizaines et 15 unités », c’est le nombre 415. Quelle est l’origine la plus probable de son erreur ?", choices: ["Il écrit les deux nombres côte à côte sans faire l’échange 10 unités = 1 dizaine", "Il confond les dizaines et les centaines", "Il a multiplié 4 par 15", "Il n’y a pas d’erreur"], answer: 0, expl: "L’élève juxtapose 4 et 15. Or 15 unités = 1 dizaine et 5 unités : on obtient 5 dizaines et 5 unités, soit <b>55</b>. Il faut retravailler les échanges avec le matériel (bûchettes, barres et cubes)." },
  { q: "Quelle propriété de notre numération illustre la phrase : « dans 333, chaque 3 n’a pas la même valeur » ?", choices: ["Son caractère décimal", "Son caractère positionnel", "La commutativité", "Son caractère additif"], answer: 1, expl: "La valeur d’un chiffre dépend de sa <b>place</b> : c’est le caractère <b>positionnel</b>. Le caractère <i>décimal</i>, lui, vient des groupements par 10 ; ne confonds pas les deux." },
  { q: "Vrai ou faux : 10⁰ = 0.", type: 'vf', answer: 1, expl: "Faux : 10⁰ = <b>1</b>. C’est pour cela que, dans une décomposition, le chiffre des unités est multiplié par 10⁰ = 1. Piège : croire que l’exposant 0 donne 0." },
  { q: "Écris (342)₅ en base 10.", answers: ["97"], expl: "En base 5, les positions valent 25, 5 et 1. Donc 3 × 25 + 4 × 5 + 2 × 1 = 75 + 20 + 2 = <b>97</b>." },
  { q: "Écris 25 en base 2 (chiffres seulement, par exemple 101).", answers: ["11001"], expl: "Puissances de 2 : 16, 8, 4, 2, 1. 25 = 16 + 8 + 1 = 1×16 + 1×8 + 0×4 + 0×2 + 1×1, donc <b>11001</b>. Vérifie toujours en recalculant la somme." },
  { q: "Combien vaut (11111)₂ en base 10 ?", choices: ["31", "32", "15", "11 111"], answer: 0, expl: "16 + 8 + 4 + 2 + 1 = <b>31</b>. Astuce : c’est 32 − 1, comme 99 999 = 100 000 − 1 en base 10." },
  { q: "Quelle est l’écriture de 100 en base 5 ?", choices: ["(400)₅", "(200)₅", "(1000)₅", "(40)₅"], answer: 0, expl: "Les positions valent 1, 5, 25, 125. Comme 125 &gt; 100, on commence par 25 : 100 = 4 × 25, reste 0. Donc 100 = <b>(400)₅</b>." },
  { q: "Laquelle de ces écritures est impossible en base 5 ?", choices: ["(240)₅", "(1304)₅", "(325)₅", "(4444)₅"], answer: 2, expl: "En base 5, on n’utilise que les chiffres 0, 1, 2, 3, 4. Le chiffre 5 n’existe pas : <b>(325)₅</b> est impossible (5 unités font déjà un groupement de 5)." },
  { q: "Quel est le successeur de (44)₅, écrit en base 5 ?", choices: ["(45)₅", "(50)₅", "(100)₅", "(110)₅"], answer: 2, expl: "(44)₅ = 4 × 5 + 4 = 24, son successeur est 25 = 1 × 25 = <b>(100)₅</b>. C’est comme 99 + 1 = 100 en base 10 : on fait un nouveau groupement à chaque rang." },
  { q: "Vrai ou faux : en base 2, l’écriture d’un nombre pair se termine toujours par 0.", type: 'vf', answer: 0, expl: "Vrai : toutes les positions sauf la dernière valent 2, 4, 8… (des nombres pairs). Le dernier chiffre est le reste de la division par 2 : il vaut 0 pour un nombre pair, 1 pour un impair." },
  { q: "Dans quelle base l’écriture « 21 » désigne-t-elle le nombre quinze ?", answers: ["7", "sept", "base 7"], expl: "En base b, « 21 » vaut 2 × b + 1. On résout 2b + 1 = 15, donc b = <b>7</b>. Vérification : (21)₇ = 14 + 1 = 15 ✔." },
  { q: "Quel est le plus petit nombre entier à 5 chiffres tous différents ?", answers: ["10234", "10 234"], expl: "Le premier chiffre ne peut pas être 0 : on met 1, puis les plus petits chiffres restants dans l’ordre : 0, 2, 3, 4. On obtient <b>10 234</b>." },
  { q: "Combien de chiffres faut-il écrire au total pour écrire tous les nombres de 1 à 99 ?", answers: ["189"], expl: "De 1 à 9 : 9 nombres à 1 chiffre → 9 chiffres. De 10 à 99 : 90 nombres à 2 chiffres → 180 chiffres. Total : 9 + 180 = <b>189</b>." },
  { q: "Quelle écriture de 80 080 est correcte (orthographe de 1990) ?", choices: ["quatre-vingt-mille-quatre-vingts", "quatre-vingts-mille-quatre-vingts", "quatre-vingt-mille-quatre-vingt", "quatre-vingts-mille-quatre-vingt"], answer: 0, expl: "« Vingt » prend un s seulement s’il est multiplié <b>et</b> termine le nombre. Devant « mille », il ne termine pas le nombre : quatre-vingt-mille. À la fin, il le termine : quatre-vingts." },
  { q: "Vrai ou faux : 200 000 s’écrit « deux-cents-mille » (orthographe de 1990).", type: 'vf', answer: 1, expl: "Faux : on écrit <b>deux-cent-mille</b>. « Cent » est multiplié mais ne termine pas le nombre, puisque « mille » le suit. Rappel : mille est invariable et ne fait pas varier « cent »." }
];

BANK['maths/2'] = [
  { q: "Calcule 36 − 12 ÷ 4 × 3.", choices: ["27", "18", "35", "33"], answer: 0, expl: "La division et la multiplication passent avant la soustraction, de gauche à droite : 12 ÷ 4 = 3, puis 3 × 3 = 9, enfin 36 − 9 = <b>27</b>. Piège : faire 4 × 3 d’abord (on obtiendrait 35)." },
  { q: "Calcule 5 + 2 × (8 − 3)².", answers: ["55"], expl: "Parenthèses : 8 − 3 = 5 ; puissance : 5² = 25 ; multiplication : 2 × 25 = 50 ; addition : 5 + 50 = <b>55</b>." },
  { q: "Calcule 100 ÷ 5 ÷ 2.", answers: ["10"], expl: "De gauche à droite : 100 ÷ 5 = 20, puis 20 ÷ 2 = <b>10</b>. Piège : calculer 5 ÷ 2 d’abord (100 ÷ 2,5 = 40) ; la division n’est pas associative." },
  { q: "Quelle expression traduit « le quotient de 24 par la somme de 2 et 6 » ?", choices: ["24 ÷ 2 + 6", "24 ÷ (2 + 6)", "(24 ÷ 2) + (24 ÷ 6)", "(2 + 6) ÷ 24"], answer: 1, expl: "Le quotient de 24 <b>par</b> quelque chose : 24 est le dividende. Ce quelque chose est une somme, qu’on doit protéger par des parenthèses : <b>24 ÷ (2 + 6)</b> = 3." },
  { q: "Calcule mentalement 125 × 32.", answers: ["4000", "4 000"], expl: "On décompose 32 = 8 × 4 et on utilise l’associativité : 125 × 8 = 1 000, puis 1 000 × 4 = <b>4 000</b>." },
  { q: "Calcule mentalement 38 × 5 + 62 × 5.", answers: ["500"], expl: "On factorise par 5 (distributivité à l’envers) : (38 + 62) × 5 = 100 × 5 = <b>500</b>. Inutile de calculer les deux produits !" },
  { q: "Quel calcul donne le même résultat que 83 − 47 ?", choices: ["86 − 50", "80 − 50", "86 − 44", "83 − 50 − 3"], answer: 0, expl: "Une différence ne change pas si on ajoute le même nombre aux deux termes : (83 + 3) − (47 + 3) = <b>86 − 50</b> = 36. C’est le principe de la soustraction par compensation." },
  { q: "Un élève pose 52 − 27 et trouve 35. Quelle est l’erreur la plus probable ?", choices: ["Dans chaque colonne, il retire le plus petit chiffre du plus grand", "Il a oublié une retenue dans une addition", "Il s’est trompé dans une table de multiplication", "Il a inversé les chiffres du résultat"], answer: 0, expl: "Aux unités, il fait 7 − 2 = 5 au lieu de « 2 − 7 impossible, je prends une dizaine ». Aux dizaines, 5 − 2 = 3. Il évite la retenue en inversant les chiffres : c’est une erreur très fréquente. Bonne réponse : 25." },
  { q: "Dans la division euclidienne de 1 000 par 37, quel est le reste ?", choices: ["1", "27", "10", "0"], answer: 0, expl: "37 × 27 = 999, donc 1 000 = 37 × 27 + <b>1</b>, avec 1 &lt; 37. Piège : donner le quotient (27) à la place du reste." },
  { q: "Une division euclidienne a pour diviseur 9, pour quotient 15 et pour reste 4. Quel est le dividende ?", answers: ["139"], expl: "On utilise a = b × q + r : a = 9 × 15 + 4 = 135 + 4 = <b>139</b>. Le reste 4 est bien inférieur à 9 ✔." },
  { q: "Vrai ou faux : l’égalité 59 = 8 × 7 + 3 traduit la division euclidienne de 59 par 7.", type: 'vf', answer: 0, expl: "Vrai : avec le diviseur 7, le quotient est 8 et le reste est 3, et on a bien 0 ≤ 3 &lt; 7. (Elle traduit aussi la division de 59 par 8, car 3 &lt; 8.)" },
  { q: "Combien de restes différents peut-on obtenir dans une division euclidienne par 7 ?", answers: ["7", "sept"], expl: "Le reste vérifie 0 ≤ r &lt; 7 : il peut valoir 0, 1, 2, 3, 4, 5 ou 6, soit <b>7</b> valeurs. Piège : oublier le reste 0 et répondre 6." },
  { q: "On distribue 250 cartes à 8 joueurs : chacun en reçoit le même nombre, le plus possible. Combien de cartes restent ?", answers: ["2"], expl: "8 × 31 = 248 et 250 − 248 = 2. Donc 250 = 8 × 31 + 2 : chaque joueur a 31 cartes et il en reste <b>2</b>." },
  { q: "175 personnes partent en sortie. Chaque car a 48 places. Combien de cars faut-il réserver ?", choices: ["3", "4", "3,6", "5"], answer: 1, expl: "175 = 48 × 3 + 31 : 3 cars ne suffisent pas, il reste 31 personnes. Il faut donc <b>4</b> cars. Le contexte impose d’arrondir au-dessus ; 3,6 n’a pas de sens pour des cars." },
  { q: "« Marc avait des billes. Il en perd 7 à la récré et il en a maintenant 25. Combien en avait-il ? » Selon Vergnaud, c’est un problème de :", choices: ["transformation, recherche de l’état initial", "composition de deux états", "comparaison", "produit de mesures"], answer: 0, expl: "Il y a un état initial inconnu, une transformation (−7) et un état final (25) : c’est une <b>transformation</b> dont on cherche l’état initial. Le mot « perd » pousse à soustraire, alors qu’il faut faire 25 + 7 = 32." },
  { q: "« Une cantine propose 4 entrées et 5 plats. Combien de menus entrée + plat différents ? » Ce problème relève :", choices: ["de la proportionnalité simple", "du produit de mesures (produit cartésien)", "de la comparaison additive", "de la division-partage"], answer: 1, expl: "On associe chaque entrée à chaque plat : c’est un <b>produit de mesures</b> (produit cartésien), 4 × 5 = 20 menus. Un arbre ou un tableau à double entrée aide les élèves." },
  { q: "« 48 élèves sont répartis en équipes de 6. Combien d’équipes ? » Il s’agit d’une division :", choices: ["partage", "quotition", "avec un reste non nul", "impossible"], answer: 1, expl: "On connaît la taille de chaque part (6) et on cherche le <b>nombre de parts</b> : c’est une division-<b>quotition</b> (48 ÷ 6 = 8). En division-partage, on connaîtrait le nombre de parts et on chercherait leur taille." },
  { q: "Vrai ou faux : la soustraction est commutative.", type: 'vf', answer: 1, expl: "Faux : 7 − 3 = 4 mais 3 − 7 = −4. Seules l’addition et la multiplication sont commutatives : on peut changer l’ordre des termes ou des facteurs." },
  { q: "Vrai ou faux : (48 ÷ 4) ÷ 2 = 48 ÷ (4 ÷ 2).", type: 'vf', answer: 1, expl: "Faux : à gauche, 12 ÷ 2 = 6 ; à droite, 48 ÷ 2 = 24. La division n’est pas associative : c’est pour cela qu’on calcule de gauche à droite." },
  { q: "Vrai ou faux : pour tout nombre a, a × 0 = 0 et a ÷ 0 = 0.", type: 'vf', answer: 1, expl: "Faux : a × 0 = 0 est vrai, mais la <b>division par 0 est impossible</b>. Aucun nombre multiplié par 0 ne redonne a (si a ≠ 0). C’est pourquoi le diviseur doit être non nul." }
];

BANK['maths/3'] = [
  { q: "Lequel de ces nombres est divisible par 3 mais pas par 9 ?", choices: ["423", "738", "516", "918"], answer: 2, expl: "Sommes des chiffres : 423 → 9 ; 738 → 18 ; 516 → 12 ; 918 → 18. Seul 12 est divisible par 3 sans l’être par 9 : <b>516</b> (= 3 × 172)." },
  { q: "Quel chiffre faut-il écrire à la place de a dans « 7a4 » pour obtenir un nombre divisible par 9 ?", answers: ["7"], expl: "La somme 7 + a + 4 = 11 + a doit être un multiple de 9. Comme a va de 0 à 9, 11 + a va de 11 à 20 : seul 18 convient, donc a = <b>7</b>. Vérification : 774 = 9 × 86 ✔." },
  { q: "Combien de diviseurs le nombre 36 possède-t-il ?", choices: ["6", "8", "9", "12"], answer: 2, expl: "On les cherche par paires : 1 × 36, 2 × 18, 3 × 12, 4 × 9, 6 × 6. Cela donne 1, 2, 3, 4, 6, 9, 12, 18, 36 : <b>9</b> diviseurs. Piège : compter 6 deux fois ; un carré parfait a un nombre impair de diviseurs." },
  { q: "Parmi ces quatre nombres, un seul est premier. Lequel ?", choices: ["119", "121", "127", "133"], answer: 2, expl: "119 = 7 × 17 ; 121 = 11² ; 133 = 7 × 19. Pour 127, on teste 2, 3, 5, 7, 11 (car 13² = 169 &gt; 127) : aucun ne le divise, donc <b>127</b> est premier." },
  { q: "Pour savoir si 221 est premier, jusqu’à quel nombre premier au maximum faut-il tester les divisions ?", answers: ["13"], expl: "On teste les nombres premiers p tels que p² ≤ 221. Or 13² = 169 ≤ 221 et 17² = 289 &gt; 221 : on va jusqu’à <b>13</b>. D’ailleurs 221 = 13 × 17 : il n’est pas premier !" },
  { q: "Vrai ou faux : un nombre premier est toujours impair.", type: 'vf', answer: 1, expl: "Faux : <b>2</b> est premier et pair (ses seuls diviseurs sont 1 et 2). C’est le seul nombre premier pair, car tout autre pair est divisible par 2." },
  { q: "Décompose 180 en produit de facteurs premiers (écris par exemple 2^3×3^2).", answers: ["2^2×3^2×5", "2²×3²×5", "2^2*3^2*5", "2^2x3^2x5", "2×2×3×3×5", "2*2*3*3*5", "2x2x3x3x5"], numeric: false, expl: "180 ÷ 2 = 90 ; 90 ÷ 2 = 45 ; 45 ÷ 3 = 15 ; 15 ÷ 3 = 5 ; 5 ÷ 5 = 1. Donc 180 = <b>2² × 3² × 5</b>. Piège : écrire 4 × 9 × 5, car 4 et 9 ne sont pas premiers." },
  { q: "Quel est le PGCD de 105 et 75 ?", choices: ["5", "15", "25", "525"], answer: 1, expl: "105 = 3 × 5 × 7 et 75 = 3 × 5². Facteurs communs avec le plus petit exposant : 3 × 5 = <b>15</b>. Attention, 525 est le PPCM, pas le PGCD." },
  { q: "Calcule PPCM(14 ; 21).", answers: ["42"], expl: "14 = 2 × 7 et 21 = 3 × 7. On prend tous les facteurs avec le plus grand exposant : 2 × 3 × 7 = <b>42</b>. Vérifie : 42 = 14 × 3 = 21 × 2 ✔." },
  { q: "Algorithme d’Euclide : 252 = 198 × 1 + 54 ; 198 = 54 × 3 + 36 ; 54 = 36 × 1 + 18 ; 36 = 18 × 2 + 0. Que vaut PGCD(252 ; 198) ?", choices: ["0", "2", "18", "36"], answer: 2, expl: "Le PGCD est le <b>dernier reste non nul</b> : <b>18</b>. Piège : prendre le dernier reste (0) ou le dernier quotient (2)." },
  { q: "Vrai ou faux : sachant que PGCD(12 ; 20) = 4, on peut en déduire que PPCM(12 ; 20) = 60.", type: 'vf', answer: 0, expl: "Vrai : PGCD × PPCM = a × b, donc PPCM = (12 × 20) ÷ 4 = 240 ÷ 4 = 60. Vérification : 60 = 12 × 5 = 20 × 3 ✔." },
  { q: "Deux guirlandes s’allument en même temps. L’une clignote toutes les 8 s, l’autre toutes les 12 s. Au bout de combien de secondes s’allument-elles de nouveau ensemble ?", answers: ["24"], expl: "On cherche le premier multiple commun : PPCM(8 ; 12). 8 = 2³ et 12 = 2² × 3, donc PPCM = 2³ × 3 = <b>24</b> s. « Se retrouver » → PPCM ; « partager en paquets » → PGCD." },
  { q: "On carrelle une pièce de 330 cm sur 240 cm avec des carreaux carrés identiques, les plus grands possible, sans découpe. Quel est le côté d’un carreau ?", choices: ["10 cm", "30 cm", "15 cm", "60 cm"], answer: 1, expl: "Le côté doit diviser 330 et 240 et être le plus grand possible : c’est PGCD(330 ; 240). 330 = 2 × 3 × 5 × 11 et 240 = 2⁴ × 3 × 5, donc PGCD = 2 × 3 × 5 = <b>30 cm</b>. 60 ne divise pas 330." },
  { q: "Lequel de ces couples est formé de deux nombres premiers entre eux ?", choices: ["14 et 21", "15 et 28", "12 et 18", "9 et 33"], answer: 1, expl: "15 = 3 × 5 et 28 = 2² × 7 n’ont aucun facteur premier commun : PGCD = 1, ils sont <b>premiers entre eux</b>. Les autres couples ont 7, 6 ou 3 comme diviseur commun. Attention : aucun des deux n’a besoin d’être premier." },
  { q: "Vrai ou faux : deux nombres pairs ne peuvent jamais être premiers entre eux.", type: 'vf', answer: 0, expl: "Vrai : deux nombres pairs sont tous deux divisibles par 2, donc leur PGCD vaut au moins 2. Ils ne peuvent pas avoir un PGCD égal à 1." },
  { q: "Écris 105/165 sous forme irréductible.", answers: ["7/11"], numeric: false, expl: "105 = 3 × 5 × 7 et 165 = 3 × 5 × 11 : leur PGCD est 15. 105 ÷ 15 = 7 et 165 ÷ 15 = 11, donc <b>7/11</b>. Diviser par le PGCD donne directement la forme irréductible." },
  { q: "Quel est le plus petit nombre non nul divisible à la fois par 2, 3, 4 et 5 ?", choices: ["120", "60", "30", "20"], answer: 1, expl: "C’est le PPCM de 2, 3, 4 et 5 : 2² × 3 × 5 = <b>60</b>. Piège : multiplier les quatre nombres (120) ; 120 convient mais n’est pas le plus petit." },
  { q: "Vrai ou faux : 0 est un multiple de 7.", type: 'vf', answer: 0, expl: "Vrai : 0 = 7 × 0, avec 0 entier. Le nombre 0 est même un multiple de tous les entiers. C’est pour cela qu’on parle du plus petit multiple commun <i>non nul</i>." },
  { q: "Un élève affirme : « 4 518 est divisible par 4, car 8 est divisible par 4 ». Que penser de sa réponse ?", choices: ["Il a raison", "Il a tort : il faut regarder le nombre formé par les deux derniers chiffres, 18, qui n’est pas divisible par 4", "Il a tort : il faut que la somme des chiffres soit divisible par 4", "Il a raison, car 4 518 est pair"], answer: 1, expl: "Le critère porte sur les <b>deux derniers chiffres</b> (car 100 est un multiple de 4) : 18 n’est pas un multiple de 4, donc 4 518 non plus (4 518 ÷ 4 = 1 129,5). L’élève confond avec le critère de divisibilité par 2." },
  { q: "Combien y a-t-il de multiples de 7 compris entre 1 et 100 ?", answers: ["14"], expl: "Les multiples de 7 sont 7 × 1, 7 × 2, …, et 7 × 14 = 98 ≤ 100 &lt; 105 = 7 × 15. Il y en a donc <b>14</b>. C’est le quotient de la division euclidienne de 100 par 7." }
];

BANK['maths/4'] = [
  { q: "Quelle fraction est égale à 3/5 ?", choices: ["9/15", "5/3", "6/8", "13/15"], answer: 0, expl: "On multiplie numérateur et dénominateur par le même nombre, 3 : 3/5 = 9/15. Piège : 6/8 ajoute 3 en haut et en bas, ce qui change la fraction." },
  { q: "Écris 56/84 sous forme irréductible.", answers: ["2/3"], numeric: false, expl: "PGCD(56 ; 84) = 28 (56 = 2³ × 7 et 84 = 2² × 3 × 7). 56 ÷ 28 = 2 et 84 ÷ 28 = 3 : <b>2/3</b>. Tu peux aussi simplifier par étapes : ÷ 4 puis ÷ 7." },
  { q: "Quelle est la plus petite de ces fractions ?", choices: ["7/8", "7/9", "7/12", "7/10"], answer: 2, expl: "Elles ont toutes le même numérateur : la plus petite est celle dont le dénominateur est le plus grand, car les parts sont plus petites. C’est <b>7/12</b>. Piège : croire que « plus grand dénominateur = plus grande fraction »." },
  { q: "Calcule 5/6 − 3/8 (forme irréductible).", answers: ["11/24"], numeric: false, expl: "Dénominateur commun : PPCM(6 ; 8) = 24. 5/6 = 20/24 et 3/8 = 9/24, donc 20/24 − 9/24 = <b>11/24</b>. On ne soustrait jamais les dénominateurs." },
  { q: "Calcule 3/10 + 4/15 (forme irréductible).", answers: ["17/30"], numeric: false, expl: "PPCM(10 ; 15) = 30. 3/10 = 9/30 et 4/15 = 8/30, donc 9/30 + 8/30 = <b>17/30</b>, déjà irréductible car 17 est premier et ne divise pas 30." },
  { q: "Combien vaut 4/9 × 15/8 (forme irréductible) ?", choices: ["5/6", "19/17", "2/3", "32/135"], answer: 0, expl: "On simplifie avant de multiplier : (4 × 15)/(9 × 8) = (4 × 3 × 5)/(3 × 3 × 4 × 2) = <b>5/6</b>. 19/17 vient d’une addition des numérateurs et des dénominateurs, 32/135 d’une division." },
  { q: "Calcule 7/4 ÷ 7/2 (forme irréductible).", answers: ["1/2", "0,5", "0.5"], numeric: false, expl: "Diviser, c’est multiplier par l’inverse : 7/4 × 2/7 = 14/28 = <b>1/2</b>. Piège : diviser les numérateurs et les dénominateurs « au hasard » sans l’inverse." },
  { q: "Combien y a-t-il de quarts de litre dans 5 L ?", choices: ["20", "5/4", "1,25", "9"], answer: 0, expl: "On cherche combien de fois 1/4 dans 5 : 5 ÷ 1/4 = 5 × 4 = <b>20</b>. Dans 1 L il y a 4 quarts, donc dans 5 L il y en a 20. Piège : calculer 5 × 1/4 = 5/4." },
  { q: "Combien valent les 3/8 de 56 ?", choices: ["21", "7", "18,7", "24"], answer: 0, expl: "Fraction-opérateur : 56 ÷ 8 = 7 (un huitième), puis 7 × 3 = <b>21</b>. Le choix 7 n’est qu’un huitième de 56." },
  { q: "Où se situe 7/3 sur une droite graduée ?", choices: ["entre 1 et 2", "entre 2 et 3", "entre 3 et 4", "entre 7 et 8"], answer: 1, expl: "7/3 = 6/3 + 1/3 = 2 + 1/3 ≈ 2,33 : le point est <b>entre 2 et 3</b>. Une fraction dont le numérateur dépasse le dénominateur est supérieure à 1." },
  { q: "Vrai ou faux : 7/3 = 2 + 1/3.", type: 'vf', answer: 0, expl: "Vrai : 7 = 3 × 2 + 1, donc 7/3 = 6/3 + 1/3 = 2 + 1/3. La division euclidienne permet d’écrire une fraction comme un entier plus une fraction inférieure à 1." },
  { q: "« 3/4, c’est le nombre qui, multiplié par 4, donne 3. » Quel sens de la fraction est utilisé ici ?", choices: ["fraction-partage", "fraction-quotient", "fraction-opérateur", "fraction-repère sur la droite graduée"], answer: 1, expl: "La fraction a/b est vue comme le résultat de la division a ÷ b, c’est-à-dire le nombre qui multiplié par b donne a : c’est la <b>fraction-quotient</b>. Le partage, lui, parle de parts d’une unité." },
  { q: "Un élève écrit 2/5 + 1/5 = 3/10. Quelle est son erreur ?", choices: ["Il additionne aussi les dénominateurs", "Il a mal simplifié", "Il a multiplié les numérateurs", "Il n’y a pas d’erreur"], answer: 0, expl: "Le dénominateur donne la <b>taille des parts</b> (des cinquièmes) : 2 cinquièmes + 1 cinquième = 3 cinquièmes, soit 3/5. L’élève traite la fraction comme deux entiers séparés." },
  { q: "Vrai ou faux : si on ajoute le même nombre au numérateur et au dénominateur, on obtient une fraction égale.", type: 'vf', answer: 1, expl: "Faux : 1/2 ≠ (1 + 1)/(2 + 1) = 2/3. On ne peut que <b>multiplier</b> ou <b>diviser</b> numérateur et dénominateur par un même nombre non nul." },
  { q: "Vrai ou faux : diviser un nombre par 1/2 revient à le multiplier par 2.", type: 'vf', answer: 0, expl: "Vrai : l’inverse de 1/2 est 2, donc a ÷ 1/2 = a × 2. Par exemple, dans 3 pizzas il y a 6 demi-pizzas. Les élèves pensent souvent que diviser rend toujours plus petit." },
  { q: "Quel est l’inverse de 0,4 ?", choices: ["5/2", "−0,4", "4/10", "0,6"], answer: 0, expl: "0,4 = 2/5, donc son inverse est <b>5/2</b> (= 2,5) : on vérifie que 0,4 × 2,5 = 1. Ne confonds pas avec l’opposé (−0,4) ni avec le complément à 1 (0,6)." },
  { q: "Dans une classe, 3/8 des élèves font du foot et 1/4 font du judo (aucun ne fait les deux). Quelle fraction des élèves ne fait ni l’un ni l’autre ?", answers: ["3/8"], numeric: false, expl: "Foot + judo : 3/8 + 2/8 = 5/8. Il reste 1 − 5/8 = 8/8 − 5/8 = <b>3/8</b>. Pense à écrire 1 sous la forme 8/8." },
  { q: "Léa dépense 1/3 de son argent, puis 1/4 de ce qui lui reste. Quelle fraction de son argent de départ lui reste-t-il ?", choices: ["5/12", "1/2", "7/12", "1/4"], answer: 1, expl: "Après la 1re dépense, il reste 2/3. Elle dépense 1/4 de 2/3, soit 1/6. Il reste 2/3 − 1/6 = 4/6 − 1/6 = 3/6 = <b>1/2</b>. Piège (5/12) : prendre 1/4 de la somme de départ au lieu de 1/4 du reste." },
  { q: "Tom a lu les 5/12 d’un livre de 240 pages. Combien de pages lui reste-t-il à lire ?", answers: ["140"], expl: "Un douzième : 240 ÷ 12 = 20 pages, donc il a lu 5 × 20 = 100 pages. Il reste 240 − 100 = <b>140</b> pages (ou directement 7/12 × 240 = 140)." },
  { q: "Vrai ou faux : la fraction 13/12 est supérieure à 1.", type: 'vf', answer: 0, expl: "Vrai : le numérateur est plus grand que le dénominateur, donc 13/12 = 1 + 1/12 &gt; 1. On a pris plus de parts qu’il n’y en a dans une unité." }
];

BANK['maths/5'] = [
  { q: "Dans 52,384, quel est le chiffre des centièmes ?", choices: ["3", "8", "4", "2"], answer: 1, expl: "Après la virgule : dixièmes (3), <b>centièmes (8)</b>, millièmes (4). Piège : chercher les « centaines » à gauche de la virgule." },
  { q: "Combien y a-t-il de dixièmes dans 52,384 ?", answers: ["523"], expl: "Comme pour les entiers, on « coupe » juste après la colonne des dixièmes : 523|84. Il y a <b>523 dixièmes</b> (52,3 = 523/10). Le <i>chiffre</i> des dixièmes, lui, est 3." },
  { q: "Écris 9/40 sous forme décimale.", answers: ["0,225", "0.225"], expl: "40 = 2³ × 5, donc la fraction est décimale. 9/40 = 225/1 000 (on multiplie par 25) = <b>0,225</b>. Tu peux aussi poser 9 ÷ 40." },
  { q: "Laquelle de ces fractions n’est PAS un nombre décimal ?", choices: ["7/8", "3/12", "5/12", "11/50"], answer: 2, expl: "On regarde la fraction <b>irréductible</b> : 5/12 l’est déjà, et 12 = 2² × 3 contient le facteur 3, donc <b>5/12</b> n’est pas décimal. Piège : 3/12 = 1/4 = 0,25 est bien décimal, il faut d’abord simplifier." },
  { q: "Range dans l’ordre croissant : 0,7 ; 0,07 ; 0,707 ; 0,77.", choices: ["0,07 &lt; 0,7 &lt; 0,707 &lt; 0,77", "0,7 &lt; 0,07 &lt; 0,77 &lt; 0,707", "0,07 &lt; 0,707 &lt; 0,7 &lt; 0,77", "0,77 &lt; 0,707 &lt; 0,7 &lt; 0,07"], answer: 0, expl: "On écrit tout avec trois décimales : 0,700 ; 0,070 ; 0,707 ; 0,770. On compare alors des millièmes : 70 &lt; 700 &lt; 707 &lt; 770, donc <b>0,07 &lt; 0,7 &lt; 0,707 &lt; 0,77</b>." },
  { q: "Un élève range ainsi : 1,9 &lt; 1,15 &lt; 1,125. Quelle conception erronée révèle ce rangement ?", choices: ["Il traite la partie décimale comme un nombre entier", "Il pense que le nombre le plus court est le plus grand", "Il ne compare que les parties entières", "Aucune : le rangement est juste"], answer: 0, expl: "Il compare 9, 15 et 125 comme des entiers. Or 1,9 = 1,900 : 900 millièmes &gt; 150 &gt; 125. Le bon ordre est 1,125 &lt; 1,15 &lt; 1,9. Remédiation : compléter par des zéros, tableau de numération." },
  { q: "Calcule 12,5 − 3,78.", answers: ["8,72", "8.72"], expl: "On aligne les virgules et on complète : 12,50 − 3,78 = <b>8,72</b>. Vérification : 8,72 + 3,78 = 12,50 ✔. Piège : aligner les chiffres à droite sans aligner les virgules." },
  { q: "Calcule 0,03 × 0,2.", answers: ["0,006", "0.006"], expl: "3 × 2 = 6 ; il y a 2 + 1 = 3 chiffres après la virgule dans les facteurs, donc <b>0,006</b>. Le résultat est plus petit que les deux facteurs, car on multiplie par des nombres inférieurs à 1." },
  { q: "Calcule 1,44 ÷ 0,12.", answers: ["12"], expl: "On rend le diviseur entier en multipliant les deux nombres par 100 : 144 ÷ 12 = <b>12</b>. Le quotient ne change pas car on multiplie dividende et diviseur par le même nombre." },
  { q: "Quel est l’ordre de grandeur de 498,7 × 0,21 ?", choices: ["10", "100", "1 000", "10 000"], answer: 1, expl: "498,7 ≈ 500 et 0,21 ≈ 0,2 : 500 × 0,2 = <b>100</b> (valeur exacte : 104,727). L’ordre de grandeur sert à contrôler un résultat obtenu à la calculatrice." },
  { q: "Arrondis 0,0965 au centième.", answers: ["0,10", "0.10", "0,1", "0.1"], expl: "On regarde le chiffre des millièmes : 6 ≥ 5, donc on arrondit au centième supérieur. 0,09 + 0,01 = <b>0,10</b>. Piège : répondre 0,09 (c’est la troncature)." },
  { q: "Quelle est la troncature au centième de 7,0491 ?", choices: ["7,04", "7,05", "7,049", "7,0"], answer: 0, expl: "Tronquer au centième, c’est garder les chiffres jusqu’aux centièmes et effacer la suite, sans regarder : 7,04|91 → <b>7,04</b>. 7,05 serait l’arrondi." },
  { q: "Écris 6 300 000 en écriture scientifique (format 6,3×10^6).", answers: ["6,3×10^6", "6.3×10^6", "6,3x10^6", "6.3x10^6", "6,3*10^6", "6.3*10^6", "6,3×10⁶", "6.3×10⁶"], numeric: false, expl: "On veut a × 10ⁿ avec 1 ≤ a &lt; 10 : a = 6,3. De 6,3 à 6 300 000, chaque chiffre avance de 6 rangs : <b>6,3 × 10⁶</b>. Piège : écrire 63 × 10⁵, qui est juste mais pas scientifique." },
  { q: "Quel nombre est égal à 4,5 × 10⁻³ ?", choices: ["0,0045", "0,045", "4 500", "−4 500"], answer: 0, expl: "10⁻³ = 0,001 : multiplier par 10⁻³, c’est diviser par 1 000. 4,5 ÷ 1 000 = <b>0,0045</b>. Un exposant négatif ne rend pas le nombre négatif." },
  { q: "Quelle est l’écriture scientifique de 52 × 10³ ?", choices: ["5,2 × 10⁴", "52 × 10³", "5,2 × 10²", "0,52 × 10⁵"], answer: 0, expl: "52 = 5,2 × 10, donc 52 × 10³ = 5,2 × 10 × 10³ = <b>5,2 × 10⁴</b>. Les autres écritures sont égales ou fausses, mais seule celle-ci a un nombre a tel que 1 ≤ a &lt; 10." },
  { q: "Multiplier un nombre par 0,01 revient à :", choices: ["le diviser par 100", "le multiplier par 100", "le diviser par 10", "lui ajouter 0,01"], answer: 0, expl: "0,01 = 1/100, donc × 0,01 = ÷ 100. Par exemple 35 × 0,01 = 0,35. C’est un résultat que beaucoup d’élèves trouvent surprenant : multiplier peut rendre plus petit." },
  { q: "Vrai ou faux : 3,4 × 10 = 3,40.", type: 'vf', answer: 1, expl: "Faux : 3,4 × 10 = <b>34</b>. 3,40 est égal à 3,4. C’est l’effet de la règle erronée « on ajoute un zéro » : avec les décimaux, ce sont les chiffres qui avancent d’un rang." },
  { q: "Vrai ou faux : il existe une infinité de nombres décimaux entre 3,1 et 3,2.", type: 'vf', answer: 0, expl: "Vrai : 3,15 ; 3,101 ; 3,1001… On peut toujours ajouter des décimales. C’est une grande différence avec les entiers : entre 3 et 4, il n’y a aucun entier." },
  { q: "Vrai ou faux : tout nombre entier est un nombre décimal.", type: 'vf', answer: 0, expl: "Vrai : un entier n peut s’écrire n/1, ou 10n/10, qui est une fraction décimale. Par exemple 7 = 70/10. Les entiers sont inclus dans les décimaux." },
  { q: "Vrai ou faux : tout nombre rationnel (toute fraction) est un nombre décimal.", type: 'vf', answer: 1, expl: "Faux : 1/3 = 0,333… est rationnel mais pas décimal, car on ne peut pas l’écrire avec une puissance de 10 au dénominateur. Les décimaux sont inclus dans les rationnels, pas l’inverse." }
];

BANK['maths/6'] = [
  { q: "Calcule (−9) + (+15) + (−8).", answers: ["-2", "−2"], expl: "(−9) + (+15) = +6, puis 6 + (−8) = <b>−2</b>. Tu peux aussi regrouper les négatifs : −17 + 15 = −2." },
  { q: "Calcule −7 − (−12).", answers: ["5"], expl: "Soustraire un nombre, c’est ajouter son opposé : −7 − (−12) = −7 + 12 = <b>5</b>. Image : enlever une dette de 12 €, c’est comme gagner 12 €." },
  { q: "Quel est le plus petit de ces nombres ?", choices: ["−0,5", "−3,2", "−3,02", "−1"], answer: 1, expl: "Pour des négatifs, le plus petit est celui qui est le plus loin de 0 : 3,2 &gt; 3,02, donc <b>−3,2</b> &lt; −3,02. Pense au thermomètre : −3,2 °C est plus froid que −3,02 °C." },
  { q: "On multiplie entre eux 15 nombres tous égaux à −2. Le résultat est :", choices: ["positif", "négatif", "nul"], answer: 1, expl: "Il y a 15 facteurs négatifs : c’est un nombre <b>impair</b>, donc le produit est <b>négatif</b> (c’est −2¹⁵ = −32 768). Avec un nombre pair de facteurs négatifs, il serait positif." },
  { q: "Calcule (−48) ÷ 6 × (−2).", answers: ["16"], expl: "De gauche à droite : (−48) ÷ 6 = −8, puis (−8) × (−2) = <b>16</b> (moins par moins donne plus)." },
  { q: "Lequel de ces nombres est égal à −25 ?", choices: ["(−5)²", "−5²", "5⁻²", "(−25)⁰"], answer: 1, expl: "Dans −5², le carré ne porte que sur 5 : −(5 × 5) = <b>−25</b>. En revanche (−5)² = 25, 5⁻² = 1/25 = 0,04 et (−25)⁰ = 1." },
  { q: "Écris 2⁻³ sous forme décimale.", answers: ["0,125", "0.125", "1/8"], expl: "2⁻³ = 1/2³ = 1/8 = <b>0,125</b>. Un exposant négatif indique un inverse, pas un nombre négatif. Piège : répondre −8 ou −6." },
  { q: "Que vaut (5²)³ ?", choices: ["5⁵", "5⁶", "5⁹", "10⁶"], answer: 1, expl: "(5²)³ = 5² × 5² × 5², soit 2 + 2 + 2 = 6 facteurs 5 : <b>5⁶</b>. Pour une puissance de puissance, on multiplie les exposants. Piège : les additionner (5⁵)." },
  { q: "On écrit 3⁷ ÷ 3⁴ sous la forme 3ⁿ. Que vaut n ?", choices: ["3", "11", "28", "7/4"], answer: 0, expl: "On simplifie 4 facteurs 3 en haut et en bas : il en reste 7 − 4 = <b>3</b>. Pour un quotient de puissances d’un même nombre, on soustrait les exposants." },
  { q: "Vrai ou faux : 2³ + 2³ = 2⁶.", type: 'vf', answer: 1, expl: "Faux : 2³ + 2³ = 8 + 8 = 16 = 2⁴ (c’est 2 × 2³). On additionne les exposants seulement pour un <b>produit</b> : 2³ × 2³ = 2⁶ = 64." },
  { q: "Combien vaut 10⁴ × 10⁻⁶ ?", choices: ["0,01", "100", "10⁻²⁴", "0,000 01"], answer: 0, expl: "On additionne les exposants : 4 + (−6) = −2, donc 10⁻² = <b>0,01</b>. 10⁻²⁴ viendrait d’une multiplication des exposants, ce qui est faux ici." },
  { q: "Calcule (−2)⁴ − 2⁴.", choices: ["0", "32", "−32", "1"], answer: 0, expl: "(−2)⁴ = (−2) × (−2) × (−2) × (−2) = 16 (4 facteurs négatifs, nombre pair) et 2⁴ = 16. Donc 16 − 16 = <b>0</b>." },
  { q: "Écris 2³ × 5³ sous la forme la plus simple.", choices: ["10³", "10⁹", "7³", "10⁶"], answer: 0, expl: "On utilise aⁿ × bⁿ = (a × b)ⁿ : 2³ × 5³ = (2 × 5)³ = <b>10³</b> = 1 000. Vérification : 8 × 125 = 1 000 ✔." },
  { q: "Vrai ou faux : √(36 × 4) = 12.", type: 'vf', answer: 0, expl: "Vrai : √(36 × 4) = √144 = 12. On peut aussi utiliser √(a × b) = √a × √b : 6 × 2 = 12. Attention, cette règle ne marche pas pour une somme." },
  { q: "Simplifie √48 (format a√b, par exemple 6√2).", answers: ["4√3", "4V3", "4racine3", "4racine(3)"], numeric: false, expl: "On cherche le plus grand carré parfait qui divise 48 : 16. √48 = √(16 × 3) = √16 × √3 = <b>4√3</b>. Piège : écrire 2√12, qui n’est pas simplifié au maximum." },
  { q: "Combien vaut (√7)² ?", choices: ["7", "49", "√14", "14"], answer: 0, expl: "Par définition, √7 est le nombre positif dont le carré vaut 7 : donc (√7)² = <b>7</b>. Le carré « annule » la racine." },
  { q: "Calcule √(25/64) (sous forme de fraction).", answers: ["5/8", "0,625", "0.625"], expl: "√(a/b) = √a / √b : √25 / √64 = <b>5/8</b>. Vérification : (5/8)² = 25/64 ✔." },
  { q: "Vrai ou faux : √9 = −3.", type: 'vf', answer: 1, expl: "Faux : (−3)² = 9, mais la racine carrée désigne le nombre <b>positif</b> dont le carré vaut 9, donc √9 = 3. L’équation x² = 9 a deux solutions (3 et −3), mais √9 n’en désigne qu’une." },
  { q: "La température passe de −6 °C à +4 °C. De combien de degrés a-t-elle augmenté ?", choices: ["2", "10", "−2", "−10"], answer: 1, expl: "On calcule l’écart : 4 − (−6) = 4 + 6 = <b>10</b> degrés (6 degrés pour remonter à 0, puis 4 de plus). Piège : faire 6 − 4 = 2." },
  { q: "Vrai ou faux : pour tout nombre a, √(a²) = a.", type: 'vf', answer: 1, expl: "Faux si a est négatif : avec a = −3, √((−3)²) = √9 = 3 ≠ −3. En fait √(a²) est la distance de a à zéro. L’égalité n’est vraie que pour a ≥ 0." }
];

BANK['maths/7'] = [
  { q: "Lequel de ces tableaux (ligne 1 → ligne 2) est un tableau de proportionnalité ?", choices: ["2 ; 5 ; 8 → 7 ; 17,5 ; 28", "2 ; 5 ; 8 → 6 ; 12 ; 24", "2 ; 5 ; 8 → 4 ; 25 ; 64", "2 ; 5 ; 8 → 5 ; 8 ; 11"], answer: 0, expl: "On calcule les quotients : 7/2 = 17,5/5 = 28/8 = 3,5, toujours le même coefficient. Dans les autres : 6/2 = 3 mais 12/5 = 2,4 ; le 3e est le carré ; le 4e ajoute 3." },
  { q: "12 L d’essence coûtent 21,60 €. Combien coûtent 5 L (en €) ?", answers: ["9", "9,00", "9.00"], expl: "Passage à l’unité : 1 L coûte 21,60 ÷ 12 = 1,80 €, donc 5 L coûtent 5 × 1,80 = <b>9 €</b>." },
  { q: "On sait que 10 cahiers coûtent 18 € et 5 cahiers 9 €. Pour trouver le prix de 15 cahiers, un élève calcule 18 + 9. Quelle procédure utilise-t-il ?", choices: ["la linéarité additive", "la linéarité multiplicative", "le passage à l’unité", "le produit en croix"], answer: 0, expl: "15 = 10 + 5, donc le prix de 15 cahiers est la somme des prix : c’est la <b>linéarité additive</b> (27 €). Un des cinq noms de procédures à connaître pour le concours." },
  { q: "Vrai ou faux : le périmètre d’un triangle équilatéral est proportionnel à la longueur de son côté.", type: 'vf', answer: 0, expl: "Vrai : P = 3 × c, on multiplie toujours par 3. Ce n’est pas le cas pour l’aire, qui ne double pas quand le côté double." },
  { q: "Calcule 35 % de 60.", answers: ["21"], expl: "35 % de 60 = 60 × 35/100 = 60 × 0,35 = <b>21</b>. Calcul mental : 10 % = 6, 30 % = 18, 5 % = 3, donc 35 % = 21." },
  { q: "Un pull à 48 € est soldé à −35 %. Quel est son nouveau prix (en €) ?", answers: ["31,2", "31,20", "31.2", "31.20"], expl: "Baisser de 35 %, c’est multiplier par 1 − 0,35 = 0,65 : 48 × 0,65 = <b>31,20 €</b>. Ou : la remise vaut 48 × 0,35 = 16,80 €, et 48 − 16,80 = 31,20 €." },
  { q: "Augmenter une quantité de 5 % revient à la multiplier par :", choices: ["1,05", "1,5", "0,05", "0,95"], answer: 0, expl: "On garde 100 % et on ajoute 5 % : 105 % = 1 + 5/100 = <b>1,05</b>. Piège : 1,5 correspond à une hausse de 50 %." },
  { q: "Après une hausse de 25 %, un loyer est de 750 €. Quel était le loyer avant la hausse (en €) ?", answers: ["600"], expl: "Ancien loyer × 1,25 = 750, donc ancien loyer = 750 ÷ 1,25 = <b>600 €</b>. Piège : enlever 25 % de 750 (on obtiendrait 562,50 €), car les 25 % portent sur l’ancien loyer." },
  { q: "Un prix baisse de 20 %. Quelle hausse faut-il ensuite appliquer pour revenir au prix initial ?", choices: ["+20 %", "+25 %", "+80 %", "+40 %"], answer: 1, expl: "Après la baisse, le prix est multiplié par 0,8. Pour revenir, il faut multiplier par 1 ÷ 0,8 = 1,25, soit une hausse de <b>25 %</b>. Exemple : 100 € → 80 € → 80 × 1,25 = 100 €." },
  { q: "18 élèves sur 24 ont réussi un test. Quel est le pourcentage de réussite ?", answers: ["75", "75 %", "75%"], expl: "18/24 = 3/4 = 0,75 = 75/100, soit <b>75 %</b>. Simplifier la fraction d’abord rend le calcul plus facile." },
  { q: "Vrai ou faux : une remise de 30 % suivie d’une remise de 10 % sur le nouveau prix équivaut à une remise de 40 %.", type: 'vf', answer: 1, expl: "Faux : on multiplie les coefficients, 0,7 × 0,9 = 0,63, soit une remise de <b>37 %</b>. La 2e remise porte sur un prix déjà réduit : les pourcentages successifs ne s’additionnent pas." },
  { q: "Sur un plan, 3 cm représentent 15 m dans la réalité. Quelle est l’échelle du plan ?", choices: ["1/5", "1/500", "1/50", "1/5 000"], answer: 1, expl: "On met les deux distances dans la même unité : 15 m = 1 500 cm. Échelle = 3/1 500 = <b>1/500</b>. Piège : oublier la conversion et trouver 1/5." },
  { q: "Sur une carte au 1/25 000, quelle longueur (en cm) représente une distance réelle de 2 km ?", answers: ["8"], expl: "2 km = 200 000 cm. Sur la carte, tout est 25 000 fois plus petit : 200 000 ÷ 25 000 = <b>8 cm</b>." },
  { q: "Un marcheur avance à 5 km/h. Combien de temps met-il pour parcourir 12 km ?", choices: ["2 h 40 min", "2 h 24 min", "2 h 04 min", "2 h 30 min"], answer: 1, expl: "t = d ÷ v = 12 ÷ 5 = 2,4 h. Or 0,4 h = 0,4 × 60 = 24 min, donc <b>2 h 24 min</b>. Piège : lire 2,4 h comme 2 h 40 min." },
  { q: "Vrai ou faux : 15 m/s = 54 km/h.", type: 'vf', answer: 0, expl: "Vrai : 1 m/s = 3,6 km/h (3 600 m en une heure), donc 15 m/s = 15 × 3,6 = 54 km/h." },
  { q: "Un coureur parcourt 10 km en 40 min. Quelle est sa vitesse moyenne en km/h ?", answers: ["15"], expl: "40 min = 40/60 h = 2/3 h. v = 10 ÷ (2/3) = 10 × 3/2 = <b>15 km/h</b>. Autre méthode : en 20 min il fait 5 km, donc en 60 min il fait 15 km." },
  { q: "Quelle représentation graphique correspond à une situation de proportionnalité ?", choices: ["Une droite passant par l’origine", "Une droite qui coupe l’axe des ordonnées en 4", "Une courbe qui passe par l’origine", "Des points alignés qui ne passent pas par l’origine"], answer: 0, expl: "Proportionnalité ⇔ y = a × x : points <b>alignés avec l’origine</b>. Il faut les deux conditions : être sur une droite <i>et</i> passer par l’origine." },
  { q: "Une recette pour 4 personnes demande 300 g de farine. Combien en faut-il pour 10 personnes ?", choices: ["750 g", "600 g", "700 g", "1 200 g"], answer: 0, expl: "Pour 2 personnes : 150 g. 10 personnes = 4 + 4 + 2, donc 300 + 300 + 150 = <b>750 g</b> (ou 300 ÷ 4 × 10). Piège : ajouter 6 parts au lieu de raisonner sur les quantités." },
  { q: "Vrai ou faux : dans le tableau 4 → 10 ; 6 → 15, le coefficient de proportionnalité est 2,5.", type: 'vf', answer: 0, expl: "Vrai : 10 ÷ 4 = 2,5 et 15 ÷ 6 = 2,5. Les deux quotients sont égaux, c’est bien un tableau de proportionnalité de coefficient 2,5." },
  { q: "Un article coûte 80 € hors taxes, avec une TVA de 20 %. Quel est son prix TTC ?", choices: ["96 €", "100 €", "64 €", "82 €"], answer: 0, expl: "Ajouter 20 %, c’est multiplier par 1,2 : 80 × 1,2 = <b>96 €</b> (la TVA vaut 16 €). Piège : 100 € viendrait de 80 + 20, en confondant 20 % et 20 €." }
];

BANK['maths/8'] = [
  { q: "Réduis : 5x² + 3x − 2x² + x.", answers: ["3x²+4x", "3x^2+4x", "4x+3x²", "4x+3x^2"], numeric: false, expl: "On regroupe les termes de même nature : 5x² − 2x² = 3x² et 3x + x = 4x. Résultat : <b>3x² + 4x</b>. On ne peut pas aller plus loin : x² et x ne s’additionnent pas." },
  { q: "Vrai ou faux : x + x + x = x³.", type: 'vf', answer: 1, expl: "Faux : x + x + x = <b>3x</b> (trois fois x). C’est x × x × x qui vaut x³. Par exemple, avec x = 2 : 2 + 2 + 2 = 6 mais 2³ = 8." },
  { q: "Développe : −2(3x − 4).", answers: ["-6x+8", "−6x+8", "8-6x", "8−6x"], numeric: false, expl: "On distribue −2 sur chaque terme : −2 × 3x = −6x et −2 × (−4) = +8. Résultat : <b>−6x + 8</b>. Piège : oublier que moins par moins donne plus (−6x − 8)." },
  { q: "Développe et réduis : (2x + 3)(x − 4).", answers: ["2x²-5x-12", "2x^2-5x-12", "2x²−5x−12", "2x^2−5x−12"], numeric: false, expl: "Double distributivité : 2x × x + 2x × (−4) + 3 × x + 3 × (−4) = 2x² − 8x + 3x − 12 = <b>2x² − 5x − 12</b>." },
  { q: "Que vaut (x − 3)² une fois développé ?", choices: ["x² − 9", "x² − 6x + 9", "x² + 9", "x² − 6x − 9"], answer: 1, expl: "(a − b)² = a² − 2ab + b² avec a = x et b = 3 : x² − 6x + 9. Piège classique : oublier le double produit (x² − 9) ou le signe de b² (qui est toujours +)." },
  { q: "Quelle est la factorisation la plus complète de 5x² + 15x ?", choices: ["5x(x + 3)", "5(x² + 15x)", "x(5x + 15)", "5x(x + 15)"], answer: 0, expl: "Le facteur commun le plus grand est 5x : 5x² = 5x × x et 15x = 5x × 3, donc <b>5x(x + 3)</b>. x(5x + 15) est juste mais incomplet (on peut encore factoriser 5)." },
  { q: "Calcule mentalement 103² à l’aide d’une identité remarquable.", choices: ["10 609", "10 009", "10 600", "10 906"], answer: 0, expl: "(100 + 3)² = 100² + 2 × 100 × 3 + 3² = 10 000 + 600 + 9 = <b>10 609</b>. Piège : 10 009 oublie le double produit." },
  { q: "Factorise 9x² − 4.", choices: ["(3x − 2)(3x + 2)", "(9x − 2)(9x + 2)", "(3x − 2)²", "(3x − 4)(3x + 1)"], answer: 0, expl: "9x² − 4 = (3x)² − 2² : c’est a² − b² = (a − b)(a + b) avec a = 3x et b = 2. Donc <b>(3x − 2)(3x + 2)</b>. Vérifie en développant : 9x² + 6x − 6x − 4 ✔." },
  { q: "Résous 4x − 9 = x + 6. x = ?", answers: ["5"], expl: "On regroupe : 4x − x = 6 + 9, soit 3x = 15, donc x = <b>5</b>. Vérification : 4 × 5 − 9 = 11 et 5 + 6 = 11 ✔." },
  { q: "Résous 2(x + 3) = 5x − 12. x = ?", answers: ["6"], expl: "On développe : 2x + 6 = 5x − 12. Puis 6 + 12 = 5x − 2x, soit 18 = 3x, donc x = <b>6</b>. Vérification : 2 × 9 = 18 et 30 − 12 = 18 ✔." },
  { q: "Quelles sont les solutions de x(2x − 6) = 0 ?", choices: ["0 et 3", "0 et −3", "3 seulement", "2 et 6"], answer: 0, expl: "Un produit est nul si l’un des facteurs est nul : x = 0 ou 2x − 6 = 0, c’est-à-dire x = 3. Solutions : <b>0 et 3</b>. Piège : diviser par x et perdre la solution 0." },
  { q: "Quelle expression traduit « le double de la somme d’un nombre x et de 5 » ?", choices: ["2x + 5", "2(x + 5)", "x² + 5", "2 + x + 5"], answer: 1, expl: "On fait d’abord la somme (x + 5), puis on la double : <b>2(x + 5)</b>. 2x + 5 serait « la somme du double de x et de 5 ». Les parenthèses changent tout." },
  { q: "La somme de trois entiers consécutifs vaut 78. Quel est le plus petit de ces entiers ?", answers: ["25"], expl: "Soit n le plus petit : n + (n + 1) + (n + 2) = 3n + 3 = 78, donc 3n = 75 et n = <b>25</b>. Vérification : 25 + 26 + 27 = 78 ✔." },
  { q: "Pour démontrer que la somme de deux entiers consécutifs est toujours impaire, quelle écriture convient ?", choices: ["n + (n + 1) = 2n + 1", "n + n = 2n", "3 + 4 = 7, donc c’est vrai", "(2n + 1) + (2n + 3) = 4n + 4"], answer: 0, expl: "Deux entiers consécutifs s’écrivent n et n + 1 ; leur somme 2n + 1 est un pair plus 1, donc <b>impaire</b> pour tout n. Un exemple (3 + 4) ne prouve rien, et la dernière écriture parle de deux impairs." },
  { q: "Vrai ou faux : vérifier une propriété sur trois exemples suffit à la démontrer.", type: 'vf', answer: 1, expl: "Faux : des exemples ne prouvent pas qu’une propriété est vraie pour <b>tous</b> les nombres. Il faut un raisonnement avec une lettre. En revanche, un seul contre-exemple suffit à prouver qu’elle est fausse." },
  { q: "f(x) = 3x − 2. Quelle est l’image de −1 par f ?", choices: ["−5", "−1", "1/3", "5"], answer: 0, expl: "On remplace x par −1 : f(−1) = 3 × (−1) − 2 = −3 − 2 = <b>−5</b>. Piège : 1/3 est l’<i>antécédent</i> de −1 (on aurait résolu 3x − 2 = −1)." },
  { q: "g est une fonction linéaire telle que g(4) = 10. Calcule g(6).", answers: ["15"], expl: "g(x) = ax avec a = 10 ÷ 4 = 2,5. Donc g(6) = 2,5 × 6 = <b>15</b>. Avec la linéarité : 6 = 4 × 1,5, donc g(6) = 10 × 1,5 = 15." },
  { q: "Vrai ou faux : la fonction f(x) = 2x + 3 est une fonction linéaire.", type: 'vf', answer: 1, expl: "Faux : c’est une fonction <b>affine</b> (ax + b avec b = 3 ≠ 0). Elle ne traduit pas la proportionnalité, car f(0) = 3 ≠ 0 : sa droite ne passe pas par l’origine." },
  { q: "Une droite passe par les points (1 ; 5) et (3 ; 11). Quel est son coefficient directeur ?", choices: ["3", "6", "2", "8"], answer: 0, expl: "a = (11 − 5)/(3 − 1) = 6/2 = <b>3</b>. Quand x augmente de 2, y augmente de 6, donc de 3 pour 1. Piège : oublier de diviser par l’écart des abscisses (6)." },
  { q: "Vrai ou faux : pour tout nombre a, (a + 1)² = a² + 1.", type: 'vf', answer: 1, expl: "Faux : (a + 1)² = a² + 2a + 1. Avec a = 3 : (3 + 1)² = 16 alors que 3² + 1 = 10. Un seul contre-exemple suffit à prouver que c’est faux." }
];

BANK['maths/9'] = [
  { q: "Convertis 0,75 km en dm.", answers: ["7500", "7 500"], expl: "Du km au dm, on descend de 4 colonnes (km, hm, dam, m, dm) : on multiplie par 10 000. 0,75 × 10 000 = <b>7 500 dm</b>." },
  { q: "Combien de litres dans 35 cL ?", choices: ["0,35 L", "3,5 L", "0,035 L", "350 L"], answer: 0, expl: "1 L = 100 cL, donc 35 cL = 35 ÷ 100 = <b>0,35 L</b>. Une canette de 33 cL fait bien un tiers de litre environ." },
  { q: "Convertis 0,6 h en minutes.", answers: ["36"], expl: "Les durées sont en base 60 : 0,6 h = 0,6 × 60 = <b>36 min</b>. Piège : répondre 60 min ou 6 min en traitant le décimal comme des minutes." },
  { q: "Un train part à 22 h 50 et arrive le lendemain à 1 h 25. Quelle est la durée du trajet ? (format 2h35)", answers: ["2h35", "2 h 35", "2h35min", "2 h 35 min"], numeric: false, expl: "On avance par étapes : 22 h 50 → 23 h 00 : 10 min ; 23 h 00 → 1 h 00 : 2 h ; 1 h 00 → 1 h 25 : 25 min. Total : <b>2 h 35 min</b>. Le passage par minuit n’est pas un obstacle si on découpe." },
  { q: "Combien font 2 h 50 min + 1 h 35 min ?", choices: ["4 h 25 min", "4 h 85 min", "3 h 25 min", "4 h 05 min"], answer: 0, expl: "2 h + 1 h = 3 h et 50 min + 35 min = 85 min = 1 h 25 min. Total : 3 h + 1 h 25 = <b>4 h 25 min</b>. Il faut convertir dès qu’on dépasse 60 min." },
  { q: "Comment s’écrit 3 h 18 min en heures décimales ?", choices: ["3,18 h", "3,3 h", "3,03 h", "3,5 h"], answer: 1, expl: "18 min = 18/60 h = 0,3 h, donc 3 h 18 min = <b>3,3 h</b>. Piège : écrire 3,18 h, comme si une heure valait 100 minutes." },
  { q: "Convertis 1,5 m² en dm².", answers: ["150"], expl: "1 m² = 10 dm × 10 dm = 100 dm², donc 1,5 m² = 1,5 × 100 = <b>150 dm²</b>. Piège : multiplier par 10 comme pour les longueurs." },
  { q: "Combien d’hectares font 0,8 km² ?", choices: ["8 ha", "80 ha", "800 ha", "8 000 ha"], answer: 1, expl: "1 km² = 100 hm² = 100 ha (on multiplie par 100 entre deux unités d’aire voisines). Donc 0,8 km² = <b>80 ha</b>." },
  { q: "Convertis 2,5 dm³ en cm³.", answers: ["2500", "2 500"], expl: "1 dm³ = 10 × 10 × 10 cm³ = 1 000 cm³, donc 2,5 dm³ = <b>2 500 cm³</b>. Pour les volumes, on multiplie par 1 000 entre deux unités voisines." },
  { q: "Une bouteille de 1,5 L a un volume intérieur de :", choices: ["1 500 cm³", "150 cm³", "15 dm³", "1,5 m³"], answer: 0, expl: "1 L = 1 dm³ = 1 000 cm³, donc 1,5 L = 1,5 dm³ = <b>1 500 cm³</b>. 1,5 m³ ferait 1 500 L, une très grosse cuve !" },
  { q: "Quelle est l’aire d’un losange de diagonales 10 cm et 6 cm (en cm²) ?", answers: ["30"], expl: "Aire du losange = (D × d) ÷ 2 = (10 × 6) ÷ 2 = <b>30 cm²</b>. Le losange occupe la moitié du rectangle de côtés 10 et 6 qui l’entoure." },
  { q: "Vrai ou faux : un parallélogramme de base 9 cm et de hauteur 4 cm a une aire de 36 cm².", type: 'vf', answer: 0, expl: "Vrai : aire = base × hauteur = 9 × 4 = 36 cm². Attention à prendre la <b>hauteur</b> (perpendiculaire à la base) et non la longueur du côté oblique." },
  { q: "Quel est le périmètre d’un cercle de diamètre 10 cm (avec π ≈ 3,14) ?", choices: ["31,4 cm", "62,8 cm", "78,5 cm", "15,7 cm"], answer: 0, expl: "P = π × diamètre = 3,14 × 10 = <b>31,4 cm</b>. 62,8 vient de 2 × π × 10 (on a pris le diamètre pour le rayon) et 78,5 est l’aire du disque de rayon 5." },
  { q: "Vrai ou faux : un carré de 4 cm de côté a « un périmètre égal à son aire », puisque 4 × 4 = 16 dans les deux cas.", type: 'vf', answer: 1, expl: "Faux : le périmètre est une <b>longueur</b> (16 cm) et l’aire une <b>surface</b> (16 cm²). Ce sont deux grandeurs différentes, qu’on ne peut pas comparer ; le nombre 16 est une coïncidence liée à l’unité choisie." },
  { q: "Quel est le volume d’un cylindre de rayon 2 cm et de hauteur 5 cm, en fonction de π ?", choices: ["20π cm³", "10π cm³", "40π cm³", "20π/3 cm³"], answer: 0, expl: "V = aire de la base × hauteur = π × 2² × 5 = π × 4 × 5 = <b>20π cm³</b>. Diviser par 3 (20π/3) donnerait le volume du cône, pas du cylindre." },
  { q: "Quel est le volume d’une pyramide à base carrée de 6 cm de côté et de hauteur 5 cm (en cm³) ?", answers: ["60"], expl: "V = (aire de la base × hauteur) ÷ 3 = (6 × 6 × 5) ÷ 3 = 180 ÷ 3 = <b>60 cm³</b>. Piège : oublier de diviser par 3 (180)." },
  { q: "Vrai ou faux : si on double le rayon d’un disque, son aire double aussi.", type: 'vf', answer: 1, expl: "Faux : quand les longueurs sont multipliées par k = 2, l’aire est multipliée par k² = <b>4</b> (π × (2r)² = 4πr²). L’aire n’est pas proportionnelle au rayon." },
  { q: "Une maquette est à l’échelle 1/10. Une pièce de la maquette a une surface de 120 cm². Quelle est la surface réelle ?", choices: ["1,2 m²", "12 m²", "0,12 m²", "1 200 cm²"], answer: 0, expl: "Les longueurs sont multipliées par 10, donc les aires par 10² = 100 : 120 × 100 = 12 000 cm² = <b>1,2 m²</b> (1 m² = 10 000 cm²). Piège : multiplier seulement par 10 (1 200 cm²)." },
  { q: "À l’école, dans quel ordre fait-on généralement travailler une grandeur comme la longueur ?", choices: ["Comparaison directe, puis mesure avec une unité non conventionnelle, puis unités usuelles", "Unités usuelles, puis comparaison directe", "Formules, puis mesure", "Unités usuelles uniquement, dès le départ"], answer: 0, expl: "On construit d’abord le <b>sens de la grandeur</b> (comparer en superposant, en reportant), puis l’idée d’unité (la main, un crayon), et seulement ensuite les unités conventionnelles (cm, m). Brûler les étapes mène aux confusions grandeur/nombre." },
  { q: "Vrai ou faux : 1 L = 1 000 cm³.", type: 'vf', answer: 0, expl: "Vrai : 1 L = 1 dm³ et 1 dm³ = 1 000 cm³. Donc aussi 1 mL = 1 cm³, ce qui permet de passer facilement des volumes aux contenances." }
];
